Before:
if(strpos($key, '|')!==false){
    $userAr = explode('|',$key);
    if(count($userAr)==2){
        global $USER;
        $USER->Authorize($userAr[0]);
    }
}

After:
if(strpos($key, '|')!==false){
    $userAr = explode('|',$key);
    if(count($userAr)==2){
        $userId = (int)$userAr[0];
        $allowed = array_filter(array_map('intval', explode(',',
            (string)\Bitrix\Main\Config\Option::get('awz.bxorm', 'impersonate_users', '')
        )));
        if($userId > 0 && in_array($userId, $allowed, true)){
            global $USER;
            $USER->Authorize($userId);
        }
        // при отсутствии userId в allowlist — НЕ авторизуем,
        // вызов продолжает работать в app-контексте без PHP-сессии
    }
}

